import os
import shutil
import sys
import thread
import ttk
from Tkinter import (BOTTOM, DISABLED, LEFT, NORMAL, RIGHT, TOP, YES, Button,
                     Entry, Frame, Label, Menu, Message, StringVar, Tk,
                     Toplevel, W, X)

from pyperclip import copy

import tkFileDialog
import tkMessageBox
from hran_pacman import cbts, fdsw, gsm, lte, sbts, wcdma
from hran_pacman.config import config


class Errorbox:
    def __init__(self, message):
        root = Tk()
        tkMessageBox.showerror(message=message)
        tkMessageBox.showwarning(message="Build name can't be empty")
        root.mainloop()


class GuiPacMan:
    def __init__(self):
        self.local_root = config.get_local_path()
        self.remote_root = config.get_remote_path()
        self.baseline = ""
        self.label_names = ["Build Name", "Local Path", "Remote Path"]
        self.root = Tk()
        self.root.resizable(1, 0)
        self.root.title("Pac-man")
        self.downloading_status = False
        self.download_status_var = StringVar(self.root)

        self.root.protocol("WM_DELETE_WINDOW", self.clean_and_destroy)

        self.all_vars = [StringVar(self.root, value=var) for var in [self.remote_root, self.local_root, self.baseline]]

        self.downloader_s = {
            cls.technology: cls
            for cls in [
                lte.LtePackageDownloader,
                sbts.SBTSPackageDownloader,
                sbts.SBTS17PackageDownloader,
                sbts.SBTS18PackageDownloader,
                cbts.CBTSPackageDownloader,
                wcdma.WCDMAPackageDownloader,
                gsm.GSMPackageDownloader,
                fdsw.FDSWPackageDownloader,
            ]
        }

        self.combobox_var = StringVar(self.root)
        self.technologies = sorted(self.downloader_s.keys())
        self.components = list()
        self.remote = False

        self.make_form()
        self.root.bind("<Return>", self.download)
        self.download_button = Button(self.root, text="Download", command=self.download)
        self.download_button.pack(side=BOTTOM, anchor=W, padx=5, pady=5)

        self.menubar = Menu(self.root)
        self.root.config(menu=self.menubar)
        self.filemenu = Menu(self.menubar, tearoff=False)
        self.menubar.add_cascade(label="File", menu=self.filemenu)
        self.submenu = Menu(self.filemenu, tearoff=False)
        self.submenu.add_command(label="Local path", command=self.change_local)
        self.submenu.add_command(label="Remote path", command=self.change_remote)
        self.menubar.add_separator()
        self.menubar.add_command(label="Copy console msg", command=self.copy_msg)
        self.filemenu.add_cascade(label="Change path", menu=self.submenu, underline=0)

        self.root.mainloop()

    def download(self):
        chosen_technology = self.combobox_var.get()
        if not chosen_technology:
            tkMessageBox.showwarning(message="Choose technology first")
        elif not self.all_vars[2].get().strip():
            tkMessageBox.showwarning(message="Build name can't be empty")
        else:
            remote_path, local_path, baseline = [i.get() for i in self.all_vars]
            downloader = self.downloader_s[chosen_technology]
            thread.start_new_thread(self.download_in_new_thread, (downloader, baseline))

    class PrintToLabel(object):
        def __init__(self, download_var):
            self.download_status_var = download_var

        def write(self, string):
            if string.strip():
                self.download_status_var.set(string)

    def download_in_new_thread(self, downloader, baseline):
        try:
            self.download_status_var.set("Status: \n Please wait until finish")
            self.dlcomplete.configure(fg="white")
            self.downloading_status = True
            self.filemenu.entryconfig(1, state=DISABLED)
            self.download_button.configure(state=DISABLED)
            sys.stdout = self.PrintToLabel(self.download_status_var)
            downloader = downloader(baseline)
            downloader.local_root = self.all_vars[1].get()
            downloader.remote_root = self.all_vars[0].get()
            downloader.progress_bar_iterations = 0
            downloader.get_package()
            self.dlcomplete.configure(fg="green")
            self.download_status_var.set("Download Complete")
        except Exception as ex:
            self.dlcomplete.configure(fg="red")
            self.download_status_var.set("Download failed with error:\n\n" + str(ex))
            self.cleanup()
            raise
        finally:
            self.downloading_status = False
            self.filemenu.entryconfig(1, state=NORMAL)
            self.download_button.configure(state=NORMAL)

    def clean_and_destroy(self):
        if self.downloading_status:
            if tkMessageBox.askokcancel(title=Warning, message=("Download still running," + " wait until complete")):
                thread.exit()
                self.cleanup()
                self.root.destroy()
        else:
            self.root.destroy()

    def cleanup(self):
        temp_container_path = os.path.join(self.all_vars[1].get(), self.all_vars[2].get())
        try:
            if self.downloading_status and os.path.exists(temp_container_path):
                shutil.rmtree(temp_container_path)
        except OSError:
            pass

    def errorbox(self, message):
        top = Toplevel(master=self.root)
        top.title("Error")
        msg = Message(top, text=message)
        msg.pack()
        button = Button(top, text="Dismiss", command=top.destroy)
        button.pack()
        top.mainloop()

    def make_form(self, remote=False):
        self.remote = remote
        width = max([len(var) for var in [self.all_vars[0].get(), self.all_vars[1].get(), self.all_vars[2].get()]])
        for frame in self.components:
            frame.destroy()

        row1 = Frame(self.root)
        tech_label = Label(row1, width=15, text="Technology", anchor="w")
        box = ttk.Combobox(row1, textvariable=self.combobox_var, state="readonly")
        box["values"] = [""] + self.technologies
        box.current()
        row1.pack(side=TOP, fill=X, padx=5, pady=5)
        tech_label.pack(side=LEFT)
        box.pack(side=LEFT)
        self.components.append(row1)

        row2 = Frame(self.root)

        entry = Entry(row2, textvariable=self.all_vars[2], width=width)
        entry.pack(side=RIGHT, expand=YES, fill=X)
        baseline_lab = Label(row2, width=15, text="Build Name:", anchor="w")
        baseline_lab.pack(side=LEFT)
        row2.pack(side=TOP, fill=X, padx=5, pady=5)
        self.components.append(row2)

        lab_text_list = ["Local Path:", "Remote Path:"]
        if not remote:
            lab_text_list = lab_text_list[:1]
        for text, variable in zip(lab_text_list, [self.all_vars[1], self.all_vars[0]]):
            row3 = Frame(self.root)
            remote_path_lab = Label(row3, width=15, text=text, anchor="w")
            remote_path_var = Label(row3, width=width, textvariable=variable, anchor="w")
            row3.pack(side=TOP, fill=X, padx=5, pady=5)
            remote_path_lab.pack(side=LEFT)
            remote_path_var.pack(side=LEFT)
            self.components.append(row3)

        row4 = Frame(self.root)
        self.dlcomplete = Label(
            row4,
            bg="black",
            fg="white",
            wraplength=450,
            width=65,
            textvariable=self.download_status_var,
            anchor="w",
            font="Helvetica 10 bold",
        )
        row4.pack(side=TOP, fill=X, padx=5, pady=5)
        self.dlcomplete.pack(side=LEFT)
        self.components.append(row4)

    def copy_msg(self):
        copy(self.download_status_var.get())

    def change_local(self):
        path = tkFileDialog.askdirectory(parent=self.root, title="Choose local directory", mustexist=True)
        if path:
            config.set_local_path(path)
            self.all_vars[1].set(path)
            self.make_form(remote=self.remote)

    def change_remote(self):
        path = tkFileDialog.askdirectory(parent=self.root, title="Choose remote directory", mustexist=True)
        if path:
            config.set_remote_path(path)
            self.all_vars[0].set(path)
            self.make_form(remote=True)


if __name__ == "__main__":
    GuiPacMan()
